#ifndef V4L2_CID_DIGITAL_GAIN
#define V4L2_CID_DIGITAL_GAIN		V4L2_CID_GAIN
#endif

// #define S5KJN5_MIPI_FREQ_356M			356000000
// #define S5KJN5_MIPI_FREQ_384M			384000000
// #define S5KJN5_MIPI_FREQ_750M			750000000
#define S5KJN5_MIPI_FREQ_1300M			650000000

#define S5KJN5_LANES			3

#define S5KJN5_XVCLK_FREQ		24000000

#define CHIP_ID				0x38e5
#define S5KJN5_REG_CHIP_ID_H		0x0000
#define S5KJN5_REG_CHIP_ID_L		0x0001

#define S5KJN5_REG_CTRL_MODE		0x0100 //ok for jn5
#define S5KJN5_MODE_SW_STANDBY		0x0000
#define S5KJN5_MODE_STREAMING		0x0100

#define S5KJN5_REG_EXPOSURE_H		0x0202 //ok for 989, coarse integration time.
#define S5KJN5_REG_EXPOSURE_L		0x0203
#define S5KJN5_EXPOSURE_MIN		2
#define S5KJN5_EXPOSURE_STEP		1
#define S5KJN5_VTS_MAX			0xffff

#define S5KJN5_REG_GAIN_H		0x0204 //ok for 989, analog gain value for long exposure frame
#define S5KJN5_REG_GAIN_L		0x0205
#define S5KJN5_GAIN_MIN			0x10
#define S5KJN5_GAIN_MAX			0x400
#define S5KJN5_GAIN_STEP		1
#define S5KJN5_GAIN_DEFAULT		0x10

//#define S5KJN5_REG_TEST_PATTERN_H	0x0600
#define S5KJN5_REG_TEST_PATTERN	0x0601
#define S5KJN5_TEST_PATTERN_ENABLE	0x1
#define S5KJN5_TEST_PATTERN_DISABLE	0x0

#define S5KJN5_REG_VTS_H		0x0340 //ok for 989, length of frame 
#define S5KJN5_REG_VTS_L		0x0341

#define S5KJN5_FLIP_MIRROR_REG		0x0101 //ok for 989, orientation for vertical
#define S5KJN5_MIRROR_BIT_MASK		BIT(0)
#define S5KJN5_FLIP_BIT_MASK		BIT(1)

#define S5KJN5_FETCH_EXP_H(VAL)		(((VAL) >> 8) & 0xFF)
#define S5KJN5_FETCH_EXP_L(VAL)		((VAL) & 0xFF)

#define S5KJN5_FETCH_AGAIN_H(VAL)		(((VAL) >> 8) & 0x03)
#define S5KJN5_FETCH_AGAIN_L(VAL)		((VAL) & 0xFF)

#define S5KJN5_FETCH_DGAIN_H(VAL)		(((VAL) >> 8) & 0x0F)
#define S5KJN5_FETCH_DGAIN_L(VAL)		((VAL) & 0xFF)

#define S5KJN5_FETCH_RHS1_H(VAL)	(((VAL) >> 16) & 0x0F)
#define S5KJN5_FETCH_RHS1_M(VAL)	(((VAL) >> 8) & 0xFF)
#define S5KJN5_FETCH_RHS1_L(VAL)	((VAL) & 0xFF)

#define REG_DELAY			0xFFFE
#define REG_NULL			0xFFFF

#define S5KJN5_REG_VALUE_08BIT		1
#define S5KJN5_REG_VALUE_16BIT		2
#define S5KJN5_REG_VALUE_24BIT		3

#define OF_CAMERA_HDR_MODE		"rockchip,camera-hdr-mode"

#define S5KJN5_NAME			"s5kjn5"

static const char * const s5kjn5_supply_names[] = {
	"avdd",		/* Analog power */
	"dovdd",	/* Digital I/O power */
	"dvdd",		/* Digital core power */
};

#define S5KJN5_NUM_SUPPLIES ARRAY_SIZE(s5kjn5_supply_names)

struct regval {
	u16 addr;
	u16 val;
};

struct other_data {
	u32 width;
	u32 height;
	u32 bus_fmt;
	u32 data_type;
	u32 data_bit;
};

struct s5kjn5_mode {
	u32 bus_fmt;
	u32 width;
	u32 height;
	struct v4l2_fract max_fps;
	u32 hts_def;
	u32 vts_def;
	u32 exp_def;
	const struct regval *global_reg_list;
	const struct regval *reg_list;
	u32 hdr_mode;
	u32 mipi_freq_idx;
	u32 pixel_rate; // pixel rate in Hz
	const struct other_data *spd;
	const struct other_data *ebd;
	u32 vc[PAD_MAX];
};

struct s5kjn5 {
	struct i2c_client	*client;
	struct clk		*xvclk;
	struct gpio_desc	*reset_gpio;
	struct gpio_desc	*pwdn_gpio;
	struct regulator_bulk_data supplies[S5KJN5_NUM_SUPPLIES];

	struct pinctrl		*pinctrl;
	struct pinctrl_state	*pins_default;
	struct pinctrl_state	*pins_sleep;

	struct v4l2_subdev	subdev;
	struct media_pad	pad;
	struct v4l2_ctrl_handler ctrl_handler;
	struct v4l2_ctrl	*exposure;
	struct v4l2_ctrl	*anal_gain;
	struct v4l2_ctrl	*digi_gain;
	struct v4l2_ctrl	*hblank;
	struct v4l2_ctrl	*vblank;
	struct v4l2_ctrl	*h_flip;
	struct v4l2_ctrl	*v_flip;
	struct v4l2_ctrl	*test_pattern;
	struct v4l2_ctrl	*pixel_rate;
	struct v4l2_ctrl	*link_freq;
	struct mutex		mutex;
	bool			streaming;
	bool			power_on;
	const struct s5kjn5_mode *cur_mode;
	u32			cfg_num;
	u32			cur_pixel_rate;
	u32			cur_link_freq;
	u32			module_index;
	const char		*module_facing;
	const char		*module_name;
	const char		*len_name;
	u32			cur_vts;
	bool			has_init_exp;
	struct preisp_hdrae_exp_s init_hdrae_exp;
	u8			flip;
	struct otp_info		*otp;
	u32			spd_id;
	u32			ebd_id;
	struct v4l2_fwnode_endpoint bus_cfg;

	struct dentry *debugfs_dir;
    struct dentry *reg_read_file;
    struct dentry *reg_write_file;
    u16 debug_reg_addr;  // 用于存储要操作的寄存器地址

	struct regval *batch_regs;     // 存储 batch 设置的寄存器
    u32 batch_reg_count;           // batch 寄存器数量
    bool apply_batch_on_stream;    // 是否在开流时应用 batch 寄存器
};

#define to_s5kjn5(sd) container_of(sd, struct s5kjn5, subdev)

static const struct other_data s5kjn5_spd = { //modified to 989, for pdaf 2048x768 L and R 
	.width = 4096,
	.height = 768,
	.bus_fmt = MEDIA_BUS_FMT_SPD_2X8,
	.data_type = 0x30,
	.data_bit = 10,
};
static const struct other_data s5kjn5_ebd = {
	.width = 4096,
	.height = 2,
	.data_type = 0x12,
	.bus_fmt = MEDIA_BUS_FMT_EBD_1X8,
};


